"""Copy Achilles results from the live DuckDB cache to PostgreSQL via Trex.

Run in the dataflow worker environment. Like MIMIC's export_data(), this uses
INSERT INTO postgres SELECT FROM duckdb. Trex already has both catalogs attached.
"""

def _sanitize_cache_id(raw_id: str) -> str:
    cleaned = raw_id.replace("-", "_")
    return f"_{cleaned}" if cleaned[:1].isdigit() else cleaned


def _quote_identifier(value: str) -> str:
    return '"' + value.replace('"', '""') + '"'

def exec(myinput):
    cache_catalog = _sanitize_cache_id(dataset_id)
    print(destination_tables)
    tables = destination_tables.split(',')

    dbdao = TrexDao(database_code=destination_database_code, cache_id=cache_catalog)

    for table in tables:
        source = f'"{cache_catalog}"."{destination_schema_name}"."{table}"'
        target = f'"{destination_database_code}__srcdb"."{destination_schema_name}"."{table}"'

        print(f"Copying {table} from cache to PostgreSQL")
        dbdao.execute_sql(f"""
            BEGIN;
            CREATE TABLE IF NOT EXISTS {target} AS
                SELECT * FROM {source} WHERE FALSE;
            TRUNCATE TABLE {target};
            INSERT INTO {target} SELECT * FROM {source};
            COMMIT;
        """)

    print("Achilles results copied to PostgreSQL")
